<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserAccessTemporalCode\Domain\ValueObject\Accessor\UserAccessTemporalCodeRecoveryCodeExpirationAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserAccessTemporalCodeRecoveryCodeExpirationAccessor trait.
 *
 * Covers null default, string/VO assignment via withRecoveryCodeExpiration,
 * getRecoveryCodeExpiration/recoveryCodeExpiration accessors, and isRecoveryCodeExpirationChanged with/without original.
 */
class UserAccessTemporalCodeRecoveryCodeExpirationAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRecoveryCodeExpiration creates a new instance with the RecoveryCodeExpiration set
     * from a string value, and getRecoveryCodeExpiration returns the primitive string.
     */
    public function testWithRecoveryCodeExpirationFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeRecoveryCodeExpirationAccessorUnitTest();

        // Act
        $result = $holder->withRecoveryCodeExpiration((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getRecoveryCodeExpiration());
    }
    /**
     * Asserts that withrecoveryCodeExpiration has access to the value object
     * from a string value, and getRecoveryCodeExpiration returns the primitive string.
     */
    public function testWithRecoveryCodeExpirationFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeRecoveryCodeExpirationAccessorUnitTest();

        // Act
        $result = $holder->withRecoveryCodeExpiration((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->recoveryCodeExpiration()->value());
    }
    public function testChangedRecoveryCodeExpiration(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeRecoveryCodeExpirationAccessorUnitTest();
        $original = $holder->withRecoveryCodeExpiration((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withRecoveryCodeExpiration((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withRecoveryCodeExpiration((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $unchanged = $holder->isRecoveryCodeExpirationChanged();
        $withSame = $original->isRecoveryCodeExpirationChanged($same);
        $withDiferent = $original->isRecoveryCodeExpirationChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserAccessTemporalCodeRecoveryCodeExpirationAccessorUnitTest
{
    use UserAccessTemporalCodeRecoveryCodeExpirationAccessor;
}
